using Microsoft.EntityFrameworkCore;
using RaceDay.Api.Models;
namespace RaceDay.Api.Data;
public class RaceDayContext(DbContextOptions<RaceDayContext> options) : DbContext(options) {
 public DbSet<Role> Roles => Set<Role>(); public DbSet<User> Users => Set<User>(); public DbSet<RaceEvent> Events => Set<RaceEvent>(); public DbSet<Category> Categories => Set<Category>(); public DbSet<EventCategory> EventCategories => Set<EventCategory>(); public DbSet<Enrolment> Enrolments => Set<Enrolment>(); public DbSet<RaceResult> Results => Set<RaceResult>();
 protected override void OnModelCreating(ModelBuilder b) {
  b.Entity<Role>(e=>{e.ToTable("Roles");e.HasKey(x=>x.RoleID);e.Property(x=>x.RoleID).HasColumnName("RoleID");e.Property(x=>x.RoleName).HasMaxLength(50).IsRequired();e.HasIndex(x=>x.RoleName).IsUnique();});
  b.Entity<User>(e=>{e.ToTable("Users");e.HasKey(x=>x.UserID);e.Property(x=>x.Email).HasMaxLength(255).IsRequired();e.HasIndex(x=>x.Email).IsUnique();e.Property(x=>x.FirstName).HasMaxLength(100).IsRequired();e.Property(x=>x.LastName).HasMaxLength(100).IsRequired();e.Property(x=>x.PasswordHash).HasMaxLength(255).IsRequired();e.Property(x=>x.CreatedAt).HasDefaultValueSql("SYSDATETIME()");e.HasOne(x=>x.Role).WithMany(x=>x.Users).HasForeignKey(x=>x.RoleID).OnDelete(DeleteBehavior.Restrict);});
  b.Entity<RaceEvent>(e=>{e.ToTable("Events",t=>t.HasCheckConstraint("CK_Events_Status","[Status] IN ('Open','Closed','Cancelled','Completed')"));e.HasKey(x=>x.EventID);e.Property(x=>x.EventName).HasMaxLength(200).IsRequired();e.Property(x=>x.Location).HasMaxLength(255).IsRequired();e.Property(x=>x.Status).HasMaxLength(30).HasDefaultValue("Open");e.Property(x=>x.EventDate).HasColumnType("date");e.Property(x=>x.CreatedAt).HasDefaultValueSql("SYSDATETIME()");e.HasOne(x=>x.Organiser).WithMany(x=>x.OrganisedEvents).HasForeignKey(x=>x.OrganiserID).OnDelete(DeleteBehavior.Restrict);});
  b.Entity<Category>(e=>{e.ToTable("Categories",t=>t.HasCheckConstraint("CK_Categories_Distance","[DistanceKm] > 0"));e.HasKey(x=>x.CategoryID);e.Property(x=>x.CategoryName).HasMaxLength(150).IsRequired();e.Property(x=>x.DistanceKm).HasColumnType("decimal(6,2)");e.HasOne(x=>x.CreatedByUser).WithMany().HasForeignKey(x=>x.CreatedByUserID).OnDelete(DeleteBehavior.Restrict);});
  b.Entity<EventCategory>(e=>{e.ToTable("EventCategories",t=>{t.HasCheckConstraint("CK_EventCategories_EntryFee","[EntryFee] >= 0");t.HasCheckConstraint("CK_EventCategories_Capacity","[Capacity] > 0");});e.HasKey(x=>new{x.EventID,x.CategoryID});e.Property(x=>x.EntryFee).HasColumnType("decimal(10,2)");e.HasOne(x=>x.Event).WithMany(x=>x.EventCategories).HasForeignKey(x=>x.EventID).OnDelete(DeleteBehavior.Cascade);e.HasOne(x=>x.Category).WithMany(x=>x.EventCategories).HasForeignKey(x=>x.CategoryID).OnDelete(DeleteBehavior.Restrict);});
  b.Entity<Enrolment>(e=>{e.ToTable("Enrolments",t=>t.HasCheckConstraint("CK_Enrolments_Status","[Status] IN ('Pending','Confirmed','Cancelled')"));e.HasKey(x=>x.EnrolmentID);e.HasIndex(x=>new{x.ParticipantID,x.EventID,x.CategoryID}).IsUnique();e.Property(x=>x.Status).HasMaxLength(30).HasDefaultValue("Confirmed");e.Property(x=>x.EnrolmentDate).HasDefaultValueSql("SYSDATETIME()");e.HasOne(x=>x.Participant).WithMany().HasForeignKey(x=>x.ParticipantID).OnDelete(DeleteBehavior.Restrict);e.HasOne(x=>x.EventCategory).WithMany(x=>x.Enrolments).HasForeignKey(x=>new{x.EventID,x.CategoryID}).OnDelete(DeleteBehavior.Restrict);});
  b.Entity<RaceResult>(e=>{e.ToTable("Results",t=>{t.HasCheckConstraint("CK_Results_Position","[Position] IS NULL OR [Position] > 0");t.HasCheckConstraint("CK_Results_Status","[Status] IN ('Recorded','Disqualified','DidNotFinish')");});e.HasKey(x=>x.ResultID);e.HasIndex(x=>x.EnrolmentID).IsUnique();e.Property(x=>x.Status).HasMaxLength(30).HasDefaultValue("Recorded");e.Property(x=>x.RecordedAt).HasDefaultValueSql("SYSDATETIME()");e.HasOne(x=>x.Enrolment).WithOne(x=>x.Result).HasForeignKey<RaceResult>(x=>x.EnrolmentID).OnDelete(DeleteBehavior.Cascade);});
 }
}
